window.LIYA_CV_B64="";
window.openLiyaCV=function(e){if(e){e.preventDefault();}var bin=atob(window.LIYA_CV_B64);var arr=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++){arr[i]=bin.charCodeAt(i);}var url=URL.createObjectURL(new Blob([arr],{type:"application/pdf"}));window.open(url,"_blank");};
